"""Freeze v1 biome selection using the original c792da7 implementation and vanilla registries."""
from pathlib import Path
import subprocess,tempfile,json
root=Path(__file__).resolve().parents[1];jdk=Path.home()/'.jdks/corretto-22.0.2/bin'
cp=(root/'preview-engine/build/runtime/java.args').read_text().splitlines()[2].strip('"')
scratch=root/'build/legacy-biomes';scratch.mkdir(parents=True,exist_ok=True)
with tempfile.TemporaryDirectory(dir=scratch) as td:
 t=Path(td).resolve();assert t.is_relative_to(scratch.resolve())
 old=t/'IslandWorldState.java';old.write_bytes(subprocess.check_output(['git','show','c792da7:common/src/main/java/org/wodichka/worldgen_editor/world/IslandWorldState.java'],cwd=root))
 source=t/'GoldenBiomes.java';source.write_text(r'''import com.google.gson.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import net.minecraft.core.*;import net.minecraft.core.registries.*;import net.minecraft.resources.*;import net.minecraft.world.level.biome.*;import org.wodichka.worldgen_editor.preview.PreviewWorld;import org.wodichka.worldgen_editor.world.*;import org.wodichka.worldgen_editor.config.*;
public class GoldenBiomes{public static void main(String[]args)throws Exception{var registry=PreviewWorld.bootstrap().registryOrThrow(Registries.BIOME);Class<?> old=IslandWorldState.class;for(var f:old.getDeclaredFields()){if(f.getType()==Holder.class){String name=f.getName().replace("Biome","").replaceAll("([a-z])([A-Z])","$1_$2").toLowerCase();if(name.equals("outer_ocean"))name="deep_ocean";f.setAccessible(true);f.set(null,registry.getHolderOrThrow(ResourceKey.create(Registries.BIOME,ResourceLocation.withDefaultNamespace(name))));}}var registryField=old.getDeclaredField("biomeRegistry");registryField.setAccessible(true);registryField.set(null,registry);var seedField=old.getDeclaredField("worldSeed");seedField.setAccessible(true);var rows=new ArrayList<Object>();for(long seed:new long[]{0,12345}){seedField.setLong(null,seed);for(String temperature:List.of("standard","cold","temperate","warm")){var config=IslandConfigLoader.parse(JsonParser.parseString("{\"enabled\":true,\"entries\":[{\"name\":\"oracle\",\"x\":0,\"z\":0,\"radius\":100,\"temperature\":\""+temperature+"\"}]}"));var info=new IslandMask(config,seed).sampleInfo(0,0).landSource();for(String id:List.of("ocean","plains","desert","snowy_plains","lush_caves","badlands","forest","river")){var biome=registry.getHolderOrThrow(ResourceKey.create(Registries.BIOME,ResourceLocation.withDefaultNamespace(id)));for(double mask:new double[]{.05,.45,1})for(int x:new int[]{0,128,-2048}){int z=-x;var land=IslandWorldState.landBiome(mask,info,biome,x,z);var ocean=IslandWorldState.oceanBiome(mask,info,biome,x,z);rows.add(Map.of("seed",Long.toString(seed),"temperature",temperature,"delegate",id,"mask",mask,"x",x,"z",z,"land",land.unwrapKey().orElseThrow().location().toString(),"ocean",ocean.unwrapKey().orElseThrow().location().toString()));}}}}System.err.println("GOLDEN="+new Gson().toJson(rows));}}''')
 subprocess.run([str(jdk/'javac.exe'),'-proc:none','-cp',cp,'-d',td,str(old),str(source)],check=True,cwd=root)
 result=subprocess.run([str(jdk/'java.exe'),'-Xmx512m','-cp',td+';'+cp,'GoldenBiomes'],check=True,capture_output=True,text=True,cwd=root)
 line=next(line.split('GOLDEN=',1)[1] for line in (result.stdout+'\n'+result.stderr).splitlines() if 'GOLDEN=' in line)
 output=root/'preview-engine/src/test/resources/legacy-biomes.json';output.parent.mkdir(parents=True,exist_ok=True);output.write_text(line+'\n');print('Golden biome cases:',len(json.loads(line)))
